/* ---- Solution ---- */
.scene {
  position: relative;
  overflow: hidden;
  border-radius: 16px;
  background-image: linear-gradient(#38bdf8, #e0f2fe);
}

.sun {
  position: absolute;
  top: 40px;
  right: 60px;
  width: 80px;
  height: 80px;
  border-radius: 50%;
  box-shadow: 0 0 0 12px rgb(250 204 21 / 0.35), 0 0 40px 20px rgb(250 204 21 / 0.5);
}

.cloud {
  position: absolute;
  border-radius: 999px;
}

.cloud-one {
  top: 70px;
  left: 50px;
  width: 140px;
  height: 44px;
}

.cloud-two {
  top: 130px;
  left: 190px;
  width: 100px;
  height: 32px;
}

.hill {
  position: absolute;
  right: -60px;
  bottom: -120px;
  left: -60px;
  height: 200px;
  border-radius: 50%;
}
